const $=s=>document.querySelector(s);let page='dashboard',products=[],customers=[],warehouses=[],docItems=[],authUser=null,selectedProductIds=new Set(),docVatMode='inclusive';
const api=async(url,opts={})=>{let r=await fetch(url,{headers:{'Content-Type':'application/json'},...opts});let raw=await r.text(),d;try{d=raw?JSON.parse(raw):{}}catch{throw Error(`Сервер вернул неожиданный ответ (HTTP ${r.status}). Проверьте публикацию и журнал Netlify.`)}if(!r.ok)throw Error(d.error||`Ошибка запроса (${r.status})`);return d};const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=n=>Number(n||0).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2});const toast=t=>{let x=$('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2600)};
function go(p){page=p;document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));const names={dashboard:'Обзор',products:'Товары',archive:'Архив товаров',stock:'Склад',movements:'Движение товаров',documents:'Документы',customers:'Клиенты',suppliers:'Поставщики',certificates:'Сертификаты и декларации',manufacturers:'Производители',backups:'Резервные копии',users:'Пользователи'};$('#page-title').textContent=names[p];render()}
document.querySelectorAll('#nav button').forEach(b=>b.onclick=()=>go(b.dataset.page));$('#today').textContent=new Date().toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'});
let renderBusy=false;async function render(){if(renderBusy)return;renderBusy=true;try{if(page==='dashboard')await dashboard();if(page==='products')await productPage();if(page==='archive')await archivePage();if(page==='stock')await stockPage();if(page==='movements')await movementPage();if(page==='customers')await simplePage('customers','Клиенты','Добавить клиента',customerForm,['name','unp','address','phone','email','bank_details']);if(page==='suppliers')await simplePage('suppliers','Поставщики','Добавить поставщика',supplierForm,['name','unp','phone','email','address']);if(page==='manufacturers')await simplePage('manufacturers','Производители','Добавить производителя',manufacturerForm,['name','country','details']);if(page==='certificates')await certPage();if(page==='documents')await documentPage();if(page==='users')await usersPage();if(page==='backups')await backupsPage()}catch(e){toast(e.message)}finally{renderBusy=false}}
async function initAuth(){try{let s=await fetch('/api/auth/status').then(r=>r.json());if(s.setup_required){authScreen(true);return}if(!s.authenticated){authScreen(false);return}authUser=s.user;$('#logout').hidden=false;$('#logout').onclick=async()=>{await fetch('/api/auth/logout',{method:'POST'});location.reload()};$('#users-nav').hidden=authUser.role!=='admin';$('#backups-nav').hidden=authUser.role!=='admin';render()}catch(e){authScreen(false,'Не удалось подключиться к серверу')}}
function authScreen(setup,error=''){let layer=document.createElement('div');layer.id='auth-layer';layer.innerHTML=`<div class="auth-card"><div class="brandmark">У</div><h1>${setup?'Первичная настройка':'Вход в систему'}</h1><p>${setup?'Создайте учётную запись администратора. Пароль должен содержать не менее 12 символов.':'Введите логин и пароль для доступа к складу и документам.'}</p><form id="auth-form"><label>Логин</label><input class="input" name="username" required minlength="3" value="${setup?'admin':''}"><label>Пароль</label><input class="input" type="password" name="password" required minlength="12" autocomplete="${setup?'new-password':'current-password'}">${setup?'<label>Повторите пароль</label><input class="input" type="password" name="confirm" required minlength="12" autocomplete="new-password">':''}<div class="auth-error" id="auth-error">${esc(error)}</div><button class="btn" type="submit">${setup?'Создать администратора':'Войти'}</button></form></div>`;document.body.appendChild(layer);$('#auth-form').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(setup&&d.password!==d.confirm){$('#auth-error').textContent='Пароли не совпадают';return}delete d.confirm;try{let r=await fetch(setup?'/api/auth/setup':'/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});let data=await r.json();if(!r.ok)throw Error(data.error||'Ошибка входа');layer.remove();initAuth()}catch(x){$('#auth-error').textContent=x.message}}}
async function usersPage(){if(authUser?.role!=='admin')return go('dashboard');let rows=await api('/api/users');$('#content').innerHTML=`<div class="panel"><div class="panelhead"><h3>Доступ к системе</h3><button class="btn" onclick="userForm()">+ Добавить пользователя</button></div><div class="notice">До трёх учётных записей. Пароли хранятся в виде криптографических хешей. Перед публикацией системы в интернете обязательно нужен HTTPS.</div><div class="tablewrap"><table><thead><tr><th>ЛОГИН</th><th>РОЛЬ</th><th>СТАТУС</th><th>СОЗДАН</th></tr></thead><tbody>${rows.map(x=>`<tr><td class="mono">${esc(x.username)}</td><td>${x.role==='admin'?'Администратор':'Сотрудник'}</td><td>${x.active?'Активен':'Отключён'}</td><td>${esc(x.created_at)}</td></tr>`).join('')}</tbody></table></div></div>`}
function userForm(){showModal('Новая учётная запись',`<form id="f" class="formgrid"><div class="field"><label>Логин *</label><input class="input" name="username" required minlength="3"></div><div class="field"><label>Роль</label><select name="role"><option value="operator">Сотрудник</option><option value="admin">Администратор</option></select></div><div class="field full"><label>Пароль (минимум 12 символов) *</label><input class="input" type="password" name="password" required minlength="12"></div><div class="field full formfoot"><button type="button" class="btn secondary" onclick="closeModal()">Отмена</button><button class="btn">Создать</button></div></form>`);$('#f').onsubmit=async e=>{e.preventDefault();try{await api('/api/users',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('Пользователь создан');render()}catch(x){toast(x.message)}}}
async function backupsPage(){
 $('#content').innerHTML=`<div class="panel"><div class="panelhead"><h3>Резервное копирование</h3><span class="muted">Только для администратора</span></div><div class="notice">Резервная копия содержит товары, архив, остатки и партии, складские операции, документы, клиентов, поставщиков, производителей, сертификаты и прикреплённые PDF-файлы. Учётные записи и пароли не перезаписываются при восстановлении.</div><div class="quick" style="margin-top:16px"><a class="btn" href="/api/backup" download>Скачать резервную копию ZIP</a><button class="btn secondary" onclick="$('#restore-backup-file').click()">Загрузить копию и восстановить</button><input id="restore-backup-file" type="file" accept=".zip,application/zip" hidden onchange="restoreBackupFile(this.files[0])"></div><div id="backup-progress" class="muted" style="margin-top:14px"></div><div class="notice" style="margin-top:16px;border-color:#b45309">Внимание: восстановление полностью заменит текущие данные резервной копией. Перед этим скачайте свежую копию текущей базы. Не закрывайте страницу до завершения.</div></div>`;
}
async function restoreBackupFile(file){
 if(!file)return;if(!file.name.toLowerCase().endsWith('.zip')){toast('Нужен ZIP-файл резервной копии');return;}
 if(file.size>100*1024*1024){toast('Максимальный размер архива — 100 МБ');return;}
 if(!confirm(`Восстановить данные из файла «${file.name}»?\n\nТекущие товары, остатки, документы и справочники будут заменены данными из архива. Сначала скачайте текущую резервную копию. Продолжить?`)){return;}
 const status=$('#backup-progress'),input=$('#restore-backup-file');if(input)input.disabled=true;
 const say=t=>{if(status)status.textContent=t};
 try{
  const chunkSize=1024*1024,total=Math.ceil(file.size/chunkSize);say('Подготавливаю загрузку…');
  const started=await api('/api/backup/restore/start',{method:'POST',body:JSON.stringify({file_name:file.name,file_size:file.size,total_chunks:total})});
  for(let i=0;i<total;i++){
   const chunk=file.slice(i*chunkSize,Math.min(file.size,(i+1)*chunkSize));
   const response=await fetch(`/api/backup/restore/chunk?id=${encodeURIComponent(started.upload_id)}&index=${i}`,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:chunk});
   if(!response.ok){let message='Не удалось загрузить часть архива';try{message=(await response.json()).error||message}catch{}throw Error(message)}
   say(`Загружаю архив: ${Math.round((i+1)/total*100)}% (${i+1}/${total})`);
  }
  say('Проверяю архив и восстанавливаю базу. Это может занять несколько минут…');
  const result=await api('/api/backup/restore/finish',{method:'POST',body:JSON.stringify({upload_id:started.upload_id})});
  const count=Object.values(result.restored||{}).reduce((a,b)=>a+Number(b||0),0);say(`Готово. Восстановлено записей: ${count}. Обновляю страницу…`);toast('Резервная копия успешно восстановлена');setTimeout(()=>location.reload(),1200);
 }catch(e){say(`Ошибка: ${e.message}`);toast(e.message)}finally{if(input)input.disabled=false; if(input)input.value='';}
}
async function dashboard(){let d=await api('/api/dashboard');$('#content').innerHTML=`<div class="grid"><div class="card stat"><div class="label">Товарных позиций</div><div class="value">${d.products}</div><div class="hint">Активный каталог</div></div><div class="card stat"><div class="label">Остаток на складах</div><div class="value">${money(d.stock_units)}</div><div class="hint">Единиц товара</div></div><div class="card stat"><div class="label">Клиенты</div><div class="value">${d.customers}</div><div class="hint">В справочнике</div></div><div class="card stat"><div class="label">Документы на проверке / срок</div><div class="value">${d.expiring}</div><div class="hint">Истекают в ближайшие 60 дней</div></div></div><div class="panel"><div class="panelhead"><h3>Быстрые действия</h3><span class="muted">Основные операции</span></div><div class="quick"><button class="btn" onclick="go('products')">+ Добавить товар</button><button class="btn" onclick="openReceive()">+ Приход товара</button><button class="btn" onclick="go('documents')">+ Создать документ</button><button class="btn" onclick="go('certificates')">Сертификаты</button><a class="btn secondary" href="/api/backup" download>Скачать резервную копию</a></div></div><div class="panel"><div class="panelhead"><h3>Последние складские операции</h3><button class="btn secondary" onclick="go('movements')">Вся история</button></div>${movementTable(d.recent)}</div><div class="notice" style="margin-top:16px">Демонстрационные данные из примера счёта загружены в каталог. Остатки пока нулевые. Сертификаты не назначены автоматически: их соответствие и актуальность нужно подтвердить.</div>`}
function movementTable(rows){return rows.length?`<div class="tablewrap"><table><thead><tr><th>ДАТА</th><th>ОПЕРАЦИЯ</th><th>АРТИКУЛ</th><th>ТОВАР</th><th>СКЛАД</th><th>КОЛИЧЕСТВО</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.created_at)}</td><td><span class="tag ${x.kind==='Приход'?'green':'orange'}">${esc(x.kind)}</span></td><td class="mono">${esc(x.article)}</td><td>${esc(x.product||x.name)}</td><td>${esc(x.warehouse)}</td><td class="mono">${money(x.qty)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Складских операций пока нет</div>'}
async function productPage(){products=await api('/api/products');$('#content').innerHTML=`<div class="panel"><div class="panelhead"><h3>Каталог товаров</h3><div class="actions"><button class="btn secondary" onclick="$('#import-file').click()">Импорт Excel</button><input id="import-file" type="file" accept=".xlsx" hidden onchange="importProducts(this.files[0])"><button class="btn" onclick="productForm()">+ Добавить товар</button></div></div><div class="toolbar"><input class="input search" id="pq" placeholder="Поиск по артикулу, названию, ТН ВЭД, производителю или сертификату..."><button class="btn secondary" onclick="loadProducts()">Найти</button></div><div class="bulkbar"><label class="bulkselect"><input type="checkbox" id="select-all-products" onchange="toggleAllProducts(this.checked)"> Выбрать все на странице</label><span id="selected-count" class="muted">Выбрано: 0</span><div class="actions"><button class="btn secondary" onclick="bulkProducts('archive')">В архив</button><button class="btn danger" onclick="bulkProducts('delete')">Удалить выбранные</button></div></div><div class="tablewrap" id="pt">${productTable(products)}</div></div>`;$('#pq').oninput=()=>loadProducts();}
async function archivePage(){const rows=await api('/api/products/archive');$('#content').innerHTML=`<div class="panel"><div class="panelhead"><h3>Архив товаров</h3><span class="muted">Позиций: ${rows.length}</span></div><div class="toolbar"><input class="input search" id="archive-q" placeholder="Поиск по артикулу или названию..."><button class="btn secondary" onclick="loadArchive()">Найти</button></div><div class="tablewrap" id="archive-table">${archiveTable(rows)}</div></div>`;$('#archive-q').oninput=()=>loadArchive();} 
async function loadArchive(){const q=$('#archive-q')?.value||'';const rows=await api('/api/products/archive?q='+encodeURIComponent(q));$('#archive-table').innerHTML=archiveTable(rows);}
function archiveTable(rows){return rows.length?`<table><thead><tr><th>АРТИКУЛ</th><th>НАИМЕНОВАНИЕ</th><th>КАТЕГОРИЯ</th><th>ОСТАТОК</th><th>ЦЕНА С НДС</th><th>ДЕЙСТВИЯ</th></tr></thead><tbody>${rows.map(x=>`<tr><td class="mono">${esc(x.article)}</td><td>${esc(x.name)}</td><td>${esc(x.category||'—')}</td><td>${money(x.stock)} ${esc(x.unit)}</td><td>${money(x.sale_price)} BYN</td><td><div class="actions"><button class="btn secondary" onclick="restoreProduct(${x.id})">Восстановить</button></div></td></tr>`).join('')}</tbody></table>`:'<div class="empty">Архив пуст</div>';}
async function restoreProduct(id){if(!confirm('Вернуть товар в активный каталог?'))return;try{await api('/api/products/'+id,{method:'PATCH',body:JSON.stringify({restore:true})});toast('Товар восстановлен');await archivePage()}catch(e){toast(e.message)}}
function productTable(rows){return rows.length?`<table><thead><tr><th><input type="checkbox" aria-label="Выбрать все" onchange="toggleAllProducts(this.checked)"></th><th>АРТИКУЛ</th><th>НАИМЕНОВАНИЕ</th><th>КОД ТН ВЭД</th><th>ПРОИЗВОДИТЕЛЬ</th><th>СЕРТИФИКАТЫ</th><th>ОСТАТОК</th><th>ЦЕНА С НДС</th><th>ЦЕНА БЕЗ НДС</th><th>ДЕЙСТВИЯ</th></tr></thead><tbody>${rows.map(x=>`<tr><td><input type="checkbox" class="product-select" value="${x.id}" ${selectedProductIds.has(Number(x.id))?'checked':''} onchange="toggleProduct(${x.id},this.checked)"></td><td class="mono">${esc(x.article)}</td><td>${esc(x.name)}</td><td class="mono">${esc(x.tnved)}</td><td>${esc(x.manufacturer||'—')}</td><td>${esc(x.certificates||'Не привязаны')}</td><td class="${x.stock>0?'stock-positive':'stock-zero'}">${money(x.stock)} ${esc(x.unit)}</td><td>${money(x.sale_price)} BYN</td><td>${money(x.sale_price_without_vat||0)} BYN</td><td><div class="actions"><button class="btn secondary" onclick="editProduct(${x.id})">Изменить</button><button class="btn secondary" onclick="archiveProduct(${x.id})">В архив</button><button class="btn danger" onclick="deleteRecord('products',${x.id})">Удалить</button></div></td></tr>`).join('')}</tbody></table>`:'<div class="empty">Товары не найдены</div>'}
function syncProductSelection(){const count=selectedProductIds.size;const el=$('#selected-count');if(el)el.textContent=`Выбрано: ${count}`;const all=$('#select-all-products');if(all)all.checked=products.length>0&&products.every(x=>selectedProductIds.has(Number(x.id)));}
function toggleProduct(id,checked){checked?selectedProductIds.add(Number(id)):selectedProductIds.delete(Number(id));syncProductSelection();}
function toggleAllProducts(checked){products.forEach(x=>checked?selectedProductIds.add(Number(x.id)):selectedProductIds.delete(Number(x.id)));const pt=$('#pt');if(pt)pt.innerHTML=productTable(products);syncProductSelection();}
async function bulkProducts(action){const ids=[...selectedProductIds];if(!ids.length)return toast('Сначала выберите товары');const verb=action==='archive'?'переместить в архив':'удалить (товары с историей будут автоматически архивированы)';if(!confirm(`Выбрано товаров: ${ids.length}. Вы уверены, что хотите ${verb}?`))return;try{const r=await api('/api/products/bulk',{method:'POST',body:JSON.stringify({ids,action})});selectedProductIds.clear();toast(`Готово. В архиве: ${r.archived}, удалено: ${r.deleted}${r.missing?`, пропущено: ${r.missing}`:''}`);await loadProducts();syncProductSelection()}catch(e){toast(e.message)}}
async function importProducts(file){
 if(!file)return;
 if(!window.XLSX){toast('Не загрузился модуль Excel. Обновите страницу и попробуйте снова.');return}
 if(!confirm(`Загрузить прайс «${file.name}»? Будут обработаны обе вкладки: основной прайс и уходящие позиции. Это может занять несколько минут.`))return;
 const input=$('#import-file');if(input)input.disabled=true;
 try{
  toast('Читаю Excel-файл…');
  const buf=await file.arrayBuffer();
  const wb=XLSX.read(buf,{type:'array',cellStyles:false,cellHTML:false,cellFormula:false,cellNF:false,cellText:false,bookVBA:false});
  const rows=[];
  for(let si=0;si<wb.SheetNames.length;si++){
   const sheetName=wb.SheetNames[si],sheet=wb.Sheets[sheetName];
   const matrix=XLSX.utils.sheet_to_json(sheet,{header:1,defval:'',raw:true});
   if(!matrix.length)continue;
   const header=matrix[0].map(x=>String(x||'').trim().toLowerCase());
   const find=(tests)=>header.findIndex(h=>tests.some(t=>h.includes(t)));
   let ai=find(['код изделия','артикул','article']),ni=find(['наименование','название','name']),pi=find(['цена byn для рб без ндс','цена без ндс','цена закупки']),pwi=find(['цена byn для рб с ндс','цена с ндс','с ндс','цена включая ндс']),vi=header.findIndex(h=>['ндс','ставка ндс','ндс %','vat','vat rate'].includes(h)||h.includes('ставка ндс')||/^(ндс|vat)(\b|\s|,|%)/.test(h));
   if(ai<0)ai=1;if(ni<0)ni=2;if(pi<0&&pwi<0)pi=3;if(vi<0)vi=4;
   const outgoing=/уходящ/i.test(sheetName);
   for(let ri=1;ri<matrix.length;ri++){
    const r=matrix[ri],article=String(r[ai]??'').trim(),name=String(r[ni]??'').trim();
    if(!article||!name||article==='#VALUE!')continue;
    const vatRaw=String(vi>=0?(r[vi]??20):20).replace(',','.');const vatParsed=Number(vatRaw);const vat=Number.isFinite(vatParsed)?vatParsed:20;
    const parsePrice=v=>{const n=Number(String(v??'').replace(/\s/g,'').replace(',','.'));return Number.isFinite(n)?n:0};
    const rawNo=pi>=0?parsePrice(r[pi]):0,rawWith=pwi>=0?parsePrice(r[pwi]):0;
    const priceNoVat=rawNo>0?rawNo:(rawWith>0?rawWith/(1+vat/100):0);
    const priceWithVat=rawWith>0?rawWith:priceNoVat*(1+vat/100);
    rows.push({article,name,unit:'шт',vat,purchase_price:priceNoVat,sale_price:Math.round(priceWithVat*10000)/10000,sale_price_without_vat:Math.round(priceNoVat*10000)/10000,active:!outgoing,category:outgoing?'Уходящие позиции':'',tnved:''});
   }
  }
  if(!rows.length)throw Error('Не удалось найти строки товаров. Проверьте заголовки Excel.');
  toast(`Подготовлено ${rows.length} позиций. Отправляю в базу…`);
  const d=await api('/api/import/products-json',{method:'POST',body:JSON.stringify({rows})});
  toast(`Импорт завершён. Новых: ${d.added}, обновлено: ${d.updated}, пропущено: ${d.skipped}. Всего: ${d.total}`);
  render();
 }catch(e){toast('Импорт не выполнен: '+e.message)}finally{if(input)input.disabled=false;if(input)input.value=''}
}
async function loadProducts(){let q=$('#pq').value;products=await api('/api/products?q='+encodeURIComponent(q));$('#pt').innerHTML=productTable(products)}
