async function stockPage(){let [rows,ps,ws,ss]=await Promise.all([api('/api/stock'),api('/api/products'),api('/api/warehouses'),api('/api/suppliers')]);products=ps;warehouses=ws;$('#content').innerHTML=`<div class="panel"><div class="panelhead"><h3>Склады</h3><button class="btn secondary" onclick="warehouseForm()">+ Добавить склад</button></div>${ws.length?`<div class="tablewrap"><table><thead><tr><th>НАЗВАНИЕ</th><th>АДРЕС</th><th>ДЕЙСТВИЯ</th></tr></thead><tbody>${ws.map(w=>`<tr><td>${esc(w.name)}</td><td>${esc(w.address||'—')}</td><td><div class="actions"><button class="btn secondary" onclick="editWarehouse(${w.id})">Изменить</button><button class="btn danger" onclick="deleteRecord('warehouses',${w.id})">Удалить</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Добавьте первый склад</div>'}</div><div class="panel"><div class="panelhead"><h3>Складские партии и остатки</h3><div class="actions"><button class="btn" onclick="openReceive()">+ Приход товара</button></div></div><div class="notice">Приход создаёт отдельную партию. Расход и реализация списываются по FIFO. Перемещения, возвраты и инвентаризация фиксируются в журнале операций.</div>${rows.length?`<div class="tablewrap"><table><thead><tr><th>АРТИКУЛ</th><th>ТОВАР</th><th>СКЛАД</th><th>ПАРТИЯ</th><th>ПОСТАВЩИК</th><th>ДОКУМЕНТ</th><th>ПОСТУПИЛО</th><th>ОСТАТОК</th></tr></thead><tbody>${rows.map(x=>`<tr><td class="mono">${esc(x.article)}</td><td>${esc(x.product)}</td><td>${esc(x.warehouse)}</td><td>${esc(x.batch_code||'—')}</td><td>${esc(x.supplier||'—')}</td><td>${esc(x.certificate||'—')}</td><td>${money(x.qty_initial)}</td><td class="mono">${money(x.qty_remaining)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Пока нет поступлений. Добавьте первую партию товара.</div>'}</div><div class="panel"><div class="panelhead"><h3>Списание товара</h3></div><form id="issue" class="formgrid"><div class="field"><label>Товар</label><select name="product_id" required>${ps.map(x=>`<option value="${x.id}">${esc(x.article)} — ${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Склад</label><select name="warehouse_id">${ws.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Количество</label><input class="input" type="number" name="qty" min="0.0001" step="0.0001" required></div><div class="field"><label>Кому / основание</label><input class="input" name="party"></div><div class="field full formfoot"><button class="btn">Списать со склада</button></div></form></div><div class="panel"><div class="panelhead"><h3>Перемещение между складами</h3></div><form id="transfer" class="formgrid"><div class="field"><label>Товар</label><select name="product_id">${ps.map(x=>`<option value="${x.id}">${esc(x.article)} — ${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Количество</label><input class="input" name="qty" type="number" min="0.0001" step="0.0001" required></div><div class="field"><label>Со склада</label><select name="from_warehouse_id">${ws.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>На склад</label><select name="to_warehouse_id">${ws.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field full formfoot"><button class="btn">Переместить</button></div></form></div><div class="panel"><div class="panelhead"><h3>Инвентаризация / корректировка</h3></div><form id="adjust" class="formgrid"><div class="field"><label>Товар</label><select name="product_id">${ps.map(x=>`<option value="${x.id}">${esc(x.article)} — ${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Склад</label><select name="warehouse_id">${ws.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Фактический остаток</label><input class="input" name="actual_qty" type="number" min="0" step="0.0001" required></div><div class="field"><label>Примечание</label><input class="input" name="notes"></div><div class="field full formfoot"><button class="btn">Сверить остаток</button></div></form></div><div class="panel"><div class="panelhead"><h3>Возврат от покупателя</h3></div><form id="stockreturn" class="formgrid"><div class="field"><label>Товар</label><select name="product_id">${ps.map(x=>`<option value="${x.id}">${esc(x.article)} — ${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Склад</label><select name="warehouse_id">${ws.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Количество</label><input class="input" name="qty" type="number" min="0.0001" step="0.0001" required></div><div class="field"><label>Клиент / документ</label><input class="input" name="party"></div><div class="field"><label>Основание / номер возврата</label><input class="input" name="ref"></div><div class="field"><label>Закупочная стоимость</label><input class="input" name="purchase_price" type="number" step="0.0001" value="0"></div><div class="field full formfoot"><button class="btn">Оформить возврат</button></div></form></div>`;$('#issue').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));try{await api('/api/stock/issue',{method:'POST',body:JSON.stringify(d)});toast('Товар списан');render()}catch(x){toast(x.message)}};$('#transfer').onsubmit=async e=>{e.preventDefault();try{await api('/api/stock/transfer',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});toast('Перемещение выполнено');render()}catch(x){toast(x.message)}};$('#adjust').onsubmit=async e=>{e.preventDefault();try{let d=Object.fromEntries(new FormData(e.target));await api('/api/stock/adjust',{method:'POST',body:JSON.stringify(d)});toast('Остаток скорректирован');render()}catch(x){toast(x.message)}};$('#stockreturn').onsubmit=async e=>{e.preventDefault();try{await api('/api/stock/return',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});toast('Возврат принят на склад');render()}catch(x){toast(x.message)}}}
async function openReceive(){let [ps,ws,ss,cs]=await Promise.all([api('/api/products'),api('/api/warehouses'),api('/api/suppliers'),api('/api/certificates')]);showModal('Поступление товара',`<form id="f" class="formgrid"><div class="field full"><label>Товар</label><select name="product_id" required>${ps.map(x=>`<option value="${x.id}">${esc(x.article)} — ${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Склад</label><select name="warehouse_id">${ws.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Поставщик</label><select name="supplier_id"><option value="">Не выбран</option>${ss.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Количество</label><input class="input" name="qty" type="number" min="0.0001" step="0.0001" required></div><div class="field"><label>Закупочная цена, BYN</label><input class="input" name="purchase_price" type="number" step="0.0001" value="0"></div><div class="field"><label>Дата поступления</label><input class="input" name="received_at" type="date" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>Номер партии / накладной</label><input class="input" name="batch_code"></div><div class="field"><label>Документ на товар</label><select name="certificate_id"><option value="">Не выбран</option>${cs.map(x=>`<option value="${x.id}">${esc(x.number)} (${esc(x.status)})</option>`).join('')}</select></div><div class="field full"><label>Примечание</label><textarea class="input" name="notes"></textarea></div><div class="field full formfoot"><button type="button" class="btn secondary" onclick="closeModal()">Отмена</button><button class="btn">Провести приход</button></div></form>`);$('#f').onsubmit=async e=>{e.preventDefault();try{await api('/api/stock/receive',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('Поступление проведено');go('stock')}catch(x){toast(x.message)}}}
