function showModal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal').classList.remove('hidden')}function closeModal(){$('#modal').classList.add('hidden')}
async function simplePage(endpoint,title,button,formfn){
 let rows=await api('/api/'+endpoint);
 let fields={customers:['name','unp','address','phone','email'],suppliers:['name','unp','phone','email','address'],manufacturers:['name','country','details']}[endpoint];
 $('#content').innerHTML=`<div class="panel"><div class="panelhead"><h3>${title}</h3><button class="btn" onclick="${formfn.name}()">+ ${button}</button></div>
 <div class="notice">Здесь можно добавлять записи, изменять их и удалять. Если запись уже используется в документах или истории, система не позволит случайно потерять связанные данные.</div>
 ${rows.length?`<div class="tablewrap"><table><thead><tr>${fields.map(f=>`<th>${({name:'НАЗВАНИЕ',unp:'УНП',address:'АДРЕС',phone:'ТЕЛЕФОН',email:'EMAIL',country:'СТРАНА',details:'ДАННЫЕ'}[f])}</th>`).join('')}<th>ДЕЙСТВИЯ</th></tr></thead><tbody>${rows.map(x=>`<tr>${fields.map(f=>`<td>${esc(x[f]||'—')}</td>`).join('')}<td><div class="actions"><button class="btn secondary" onclick="editSimple('${endpoint}',${x.id})">Изменить</button><button class="btn danger" onclick="deleteRecord('${endpoint}',${x.id})">Удалить</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Записей пока нет</div>'}</div>`;
}
async function editSimple(endpoint,id){
 const rows=await api('/api/'+endpoint),r=rows.find(x=>Number(x.id)===Number(id));if(!r)return;
 const fields={customers:['name','unp','address','phone','email','bank_details','notes'],suppliers:['name','unp','phone','email','address','notes'],manufacturers:['name','country','details']}[endpoint];
 const labels={name:'Название',unp:'УНП',address:'Адрес',phone:'Телефон',email:'Email',bank_details:'Банковские реквизиты',notes:'Примечание',country:'Страна',details:'Дополнительные сведения'};
 showModal('Редактирование',`<form id="f" class="formgrid">${fields.map(k=>`<div class="field ${['address','bank_details','details','notes'].includes(k)?'full':''}"><label>${labels[k]}</label><input class="input" name="${k}" value="${esc(r[k]||'')}"></div>`).join('')}<div class="field full formfoot"><button type="button" class="btn secondary" onclick="closeModal()">Отмена</button><button class="btn">Сохранить</button></div></form>`);
 $('#f').onsubmit=async e=>{e.preventDefault();try{await api(`/api/${endpoint}/${id}`,{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('Изменения сохранены');render()}catch(x){toast(x.message)}};
}
async function deleteRecord(endpoint,id){if(!confirm('Удалить запись? Если она используется в истории или документах, система сохранит её и объяснит причину.'))return;try{const d=await api(`/api/${endpoint}/${id}`,{method:'DELETE'});toast(d.archived?'Есть история — запись перемещена в архив':'Запись удалена');render()}catch(e){toast(e.message)}}

function customerForm(){showModal('Новый клиент',genericForm(['name','unp','address','phone','email','bank_details'],['Название / ФИО','УНП','Адрес','Телефон','Email','Банковские реквизиты']))}function supplierForm(){showModal('Новый поставщик',genericForm(['name','unp','phone','email','address'],['Название','УНП','Телефон','Email','Адрес']))}function manufacturerForm(){showModal('Новый производитель',genericForm(['name','country','details'],['Название','Страна','Дополнительные сведения']))}
function genericForm(keys,labels){return `<form id="f" class="formgrid">${keys.map((k,i)=>`<div class="field ${['address','bank_details','details'].includes(k)?'full':''}"><label>${labels[i]}${i===0?' *':''}</label><input class="input" name="${k}" ${i===0?'required':''}></div>`).join('')}<div class="field full formfoot"><button type="button" class="btn secondary" onclick="closeModal()">Отмена</button><button class="btn">Сохранить</button></div></form>`}
async function bindSimple(endpoint){$('#f').onsubmit=async e=>{e.preventDefault();try{await api('/api/'+endpoint,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('Сохранено');render()}catch(x){toast(x.message)}}} // attached by form-specific wrappers below
const oldCustomer=customerForm;customerForm=function(){oldCustomer();bindSimple('customers')};const oldSupplier=supplierForm;supplierForm=function(){oldSupplier();bindSimple('suppliers')};const oldManufacturer=manufacturerForm;manufacturerForm=function(){oldManufacturer();bindSimple('manufacturers')};
async function certPage(){let [rows,mans,catalog,files]=await Promise.all([api('/api/certificates'),api('/api/manufacturers'),api('/api/certificate-catalog'),api('/api/certificate-files')]);$('#content').innerHTML=`<div class="panel"><div class="panelhead"><h3>Сертификаты и декларации</h3><button class="btn" onclick="certificateForm()">+ Добавить документ</button></div><div class="notice">Импортированный список и PDF сохраняются в системе. Автоматически извлечённые сведения получают статус «На проверке» — до ручной сверки они не считаются подтверждёнными.</div><div class="quick" style="margin-top:14px"><span class="btn secondary" style="opacity:.75;cursor:default">Список продукции загружен: 241 строка</span><label class="btn secondary" for="cert-pdf-file">Загрузить PDF сертификата</label><input id="cert-pdf-file" type="file" accept="application/pdf,.pdf" hidden onchange="uploadCertificatePdf(this.files[0])"></div><h3 style="margin-top:24px">Реестр документов</h3>${rows.length?`<div class="tablewrap"><table><thead><tr><th>НОМЕР</th><th>ТИП</th><th>ПРОИЗВОДИТЕЛЬ</th><th>ВЫДАН</th><th>ДЕЙСТВУЕТ ДО</th><th>СТАТУС</th><th>ДЕЙСТВИЯ</th></tr></thead><tbody>${rows.map(x=>`<tr><td class="mono">${esc(x.number)}</td><td>${esc(x.doc_type)}</td><td>${esc(x.manufacturer||'—')}</td><td>${esc(x.issue_date||'—')}</td><td>${esc(x.expiry_date||'—')}</td><td><span class="tag ${(x.effective_status||x.status)==='Действует'?'green':(x.effective_status||x.status)==='Истёк'?'red':'orange'}">${esc(x.effective_status||x.status)}</span></td><td><div class="actions"><button class="btn secondary" onclick="editCertificate(${x.id})">Изменить</button><button class="btn secondary" onclick="attachCertificate(${x.id})">Привязать товар</button><button class="btn danger" onclick="deleteRecord('certificates',${x.id})">Удалить</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Документы ещё не добавлены</div>'}<h3 style="margin-top:24px">Номенклатура из списка собственного производства</h3><div class="toolbar"><input class="input search" id="certq" placeholder="Поиск по коду товара, названию, ТН ВЭД или сертификату..."><button class="btn secondary" onclick="searchCertificateCatalog()">Найти</button></div><div id="cert-catalog-results">${certificateCatalogTable(catalog)}</div><h3 style="margin-top:24px">Загруженные PDF</h3>${files.length?`<div class="tablewrap"><table><thead><tr><th>ФАЙЛ</th><th>НОМЕР В РЕЕСТРЕ</th><th>ЗАГРУЖЕН</th></tr></thead><tbody>${files.map(f=>`<tr><td><a href="/certificate-files/${f.id}" target="_blank" rel="noopener">${esc(f.original_name)}</a></td><td class="mono">${esc(f.certificate_number||'Не распознан')}</td><td>${esc(f.uploaded_at)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">PDF пока не загружены</div>'}</div>`}
function certificateCatalogTable(rows){return rows.length?`<div class="tablewrap"><table><thead><tr><th>КОД ТОВАРА</th><th>НАИМЕНОВАНИЕ ИЗ ДОКУМЕНТА</th><th>ТН ВЭД ЕАЭС</th><th>СЕРТИФИКАТ</th><th>СРОК ДО</th><th>СОПОСТАВЛЕНИЕ</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td class="mono">${esc(x.product_code||'—')}</td><td>${esc(x.description)}</td><td class="mono">${esc(x.tnved||'—')}</td><td class="mono">${esc(x.certificate_number)}</td><td>${esc(x.expiry_date||'—')}</td><td>${x.linked_product?`<span class="tag green">${esc(x.linked_article)} — ${esc(x.linked_product)}</span>`:`<span class="tag orange">${esc(x.effective_status||x.review_status)}</span>`}</td><td><button class="btn secondary" onclick="mapCatalogItem(${x.id})">${x.linked_product?'Изменить связь':'Сопоставить'}</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Строки списка пока не импортированы</div>'}
async function searchCertificateCatalog(){let q=$('#certq')?.value||'';let rows=await api('/api/certificate-catalog?q='+encodeURIComponent(q));$('#cert-catalog-results').innerHTML=certificateCatalogTable(rows)}
async function mapCatalogItem(itemId){let ps=await api('/api/products');let rows=await api('/api/certificate-catalog');let item=rows.find(x=>x.id===itemId);showModal('Сопоставить строку сертификата с товаром',`<div class="notice">Сверьте артикул и описание с карточкой товара. Привязка добавит сертификат к товару, но не подтвердит юридическую действительность документа.</div><p><b>${esc(item?.description||'')}</b><br><span class="muted">Сертификат ${esc(item?.certificate_number||'')} · ТН ВЭД ${esc(item?.tnved||'—')}</span></p><form id="f" class="formgrid"><div class="field full"><label>Карточка товара</label><select name="product_id" required>${ps.map(x=>`<option value="${x.id}" ${x.article===item?.linked_article?'selected':''}>${esc(x.article)} — ${esc(x.name)}</option>`).join('')}</select></div><div class="field full formfoot"><button type="button" class="btn secondary" onclick="closeModal()">Отмена</button><button class="btn">Подтвердить сопоставление</button></div></form>`);$('#f').onsubmit=async e=>{e.preventDefault();try{await api('/api/certificate-catalog/'+itemId+'/link',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('Связь сохранена. Проверьте оригинал сертификата.');render()}catch(x){toast(x.message)}}}
async function editWarehouse(id){const rows=await api('/api/warehouses'),w=rows.find(x=>Number(x.id)===Number(id));if(!w)return;showModal('Изменить склад',`<form id="f" class="formgrid"><div class="field full"><label>Название склада *</label><input class="input" name="name" required value="${esc(w.name)}"></div><div class="field full"><label>Адрес</label><input class="input" name="address" value="${esc(w.address||'')}"></div><div class="field full formfoot"><button type="button" class="btn secondary" onclick="closeModal()">Отмена</button><button class="btn">Сохранить</button></div></form>`);$('#f').onsubmit=async e=>{e.preventDefault();try{await api('/api/warehouses/'+id,{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('Склад обновлён');render()}catch(x){toast(x.message)}}}
function warehouseForm(){showModal('Новый склад',`<form id="f" class="formgrid"><div class="field full"><label>Название склада *</label><input class="input" name="name" required></div><div class="field full"><label>Адрес</label><input class="input" name="address"></div><div class="field full formfoot"><button type="button" class="btn secondary" onclick="closeModal()">Отмена</button><button class="btn">Добавить склад</button></div></form>`);$('#f').onsubmit=async e=>{e.preventDefault();try{await api('/api/warehouses',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('Склад добавлен');render()}catch(x){toast(x.message)}}}
async function importCertificateList(file){if(!file)return;let fd=new FormData();fd.append('file',file);try{let r=await fetch('/api/import/certificate-list',{method:'POST',body:fd});let d=await r.json();if(!r.ok)throw Error(d.error||'Ошибка импорта');toast(`Импортировано строк: ${d.imported}. Сертификатов: ${d.certificates}. Требуют проверки.`);render()}catch(e){toast(e.message)}finally{$('#cert-list-file').value=''}}
async function uploadCertificatePdf(file){if(!file)return;let fd=new FormData();fd.append('file',file);try{let r=await fetch('/api/certificate-files',{method:'POST',body:fd});let d=await r.json();if(!r.ok)throw Error(d.error||'Ошибка загрузки');toast(d.number_detected?`PDF сохранён. Распознан номер ${d.number_detected}; проверьте даты.`:'PDF сохранён. Номер не распознан — внесите его вручную.');render()}catch(e){toast(e.message)}finally{$('#cert-pdf-file').value=''}}
async function certificateForm(){let mans=await api('/api/manufacturers');showModal('Новый сертификат / декларация',`<form id="f" class="formgrid"><div class="field"><label>Номер документа *</label><input class="input" name="number" required></div><div class="field"><label>Тип документа</label><select name="doc_type"><option>Сертификат</option><option>Декларация</option><option>Иное</option></select></div><div class="field"><label>Производитель</label><select name="manufacturer_id"><option value="">Не выбран</option>${mans.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Статус проверки</label><select name="status"><option>На проверке</option><option>Действует</option><option>Истёк</option><option>Приостановлен</option></select></div><div class="field"><label>Дата выдачи</label><input class="input" type="date" name="issue_date"></div><div class="field"><label>Действует до</label><input class="input" type="date" name="expiry_date"></div><div class="field full"><label>Примечание</label><textarea class="input" name="notes"></textarea></div><div class="field full formfoot"><button type="button" class="btn secondary" onclick="closeModal()">Отмена</button><button class="btn">Сохранить</button></div></form>`);$('#f').onsubmit=async e=>{e.preventDefault();try{await api('/api/certificates',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('Документ добавлен');render()}catch(x){toast(x.message)}}}
async function editCertificate(id){let c=(await api('/api/certificates')).find(x=>x.id===id);if(!c)return;let mans=await api('/api/manufacturers');showModal('Проверка и редактирование сертификата',`<form id="f" class="formgrid"><div class="field"><label>Номер документа</label><input class="input" name="number" required value="${esc(c.number)}"></div><div class="field"><label>Тип</label><select name="doc_type"><option ${c.doc_type==='Сертификат'?'selected':''}>Сертификат</option><option ${c.doc_type==='Декларация'?'selected':''}>Декларация</option><option ${c.doc_type==='Иное'?'selected':''}>Иное</option></select></div><div class="field"><label>Производитель</label><select name="manufacturer_id"><option value="">Не выбран</option>${mans.map(m=>`<option value="${m.id}" ${m.id==c.manufacturer_id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div><div class="field"><label>Статус проверки</label><select name="status">${['На проверке','Действует','Истёк','Приостановлен'].map(v=>`<option ${c.status===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Дата выдачи</label><input class="input" type="date" name="issue_date" value="${esc(c.issue_date)}"></div><div class="field"><label>Действует до</label><input class="input" type="date" name="expiry_date" value="${esc(c.expiry_date)}"></div><div class="field full"><label>Примечание / результат проверки оригинала</label><textarea class="input" name="notes">${esc(c.notes)}</textarea></div><div class="field full formfoot"><button type="button" class="btn secondary" onclick="closeModal()">Отмена</button><button class="btn">Сохранить</button></div></form>`);$('#f').onsubmit=async e=>{e.preventDefault();try{await api('/api/certificates/'+id,{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('Реквизиты сертификата обновлены');render()}catch(x){toast(x.message)}}}
async function attachCertificate(certId){let ps=await api('/api/products');showModal('Привязать документ к товару',`<form id="f" class="formgrid"><div class="field full"><label>Товар</label><select name="product_id">${ps.map(x=>`<option value="${x.id}">${esc(x.article)} — ${esc(x.name)}</option>`).join('')}</select></div><div class="field full formfoot"><button type="button" class="btn secondary" onclick="closeModal()">Отмена</button><button class="btn">Привязать</button></div></form>`);$('#f').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));d.certificate_id=certId;try{await api('/api/product-certificates',{method:'POST',body:JSON.stringify(d)});closeModal();toast('Документ привязан к товару');render()}catch(x){toast(x.message)}}}
async function documentPage(){let [docs,cs,ps]=await Promise.all([api('/api/documents'),api('/api/customers'),api('/api/document-products')]);customers=cs;products=ps;$('#content').innerHTML=`<div class="panel"><div class="panelhead"><h3>Документы реализации</h3><button class="btn" onclick="newDocument()">+ Создать документ</button></div>${docs.length?`<div class="tablewrap"><table><thead><tr><th>НОМЕР</th><th>ДАТА</th><th>ТИП</th><th>КЛИЕНТ</th><th>СКЛАД</th><th>РЕЖИМ НДС</th><th>СТАТУС</th><th>ВЫГРУЗКА / ДЕЙСТВИЯ</th></tr></thead><tbody>${docs.map(x=>`<tr><td class="mono">${esc(x.doc_no||'#'+x.id)}</td><td>${esc(x.doc_date)}</td><td>${esc(x.doc_type)}</td><td>${esc(x.customer||'—')}</td><td>${esc(x.warehouse||'Основной склад')}</td><td>${x.vat_mode==='exclusive'?'НДС сверху':x.vat_mode==='none'?'Без НДС':'Цена с НДС'}</td><td><span class="tag">${esc(x.effective_status||x.status)}</span></td><td><div class="actions"><button class="btn secondary" onclick="exportDoc(${x.id},'xlsx')">Excel</button><button class="btn secondary" onclick="exportDoc(${x.id},'pdf')">PDF</button>${x.status==='Черновик'?`<button class="btn" onclick="postDocument(${x.id})">Провести</button><button class="btn danger" onclick="deleteRecord('documents',${x.id})">Удалить</button>`:''}${x.status==='Отменён'?`<button class="btn danger" onclick="deleteRecord('documents',${x.id})">Удалить</button>`:''}${x.status==='Проведён'?`<button class="btn danger" onclick="cancelDocument(${x.id})">Отменить</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Документов пока нет</div>'}</div>`}
async function postDocument(id){if(!confirm('Провести документ и списать товары с основного склада по FIFO?'))return;try{await api('/api/documents/'+id+'/post',{method:'POST',body:JSON.stringify({})});toast('Документ проведён, склад списан');render()}catch(e){toast(e.message)}}async function cancelDocument(id){if(!confirm('Отменить проведение? Будут созданы обратные складские движения.'))return;try{await api('/api/documents/'+id+'/cancel',{method:'POST',body:JSON.stringify({})});toast('Проведение отменено');render()}catch(e){toast(e.message)}}
async function newDocument(){let [cs,ps,ws]=await Promise.all([api('/api/customers'),api('/api/document-products'),api('/api/warehouses')]);products=ps;docItems=[];docVatMode='inclusive';showModal('Новый документ реализации',`<form id="docform"><div class="formgrid"><div class="field"><label>Номер документа</label><input class="input" name="doc_no" placeholder="Например, 001"></div><div class="field"><label>Дата</label><input class="input" name="doc_date" type="date" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>Клиент</label><select name="customer_id"><option value="">Не выбран</option>${cs.map(x=>`<option value="${x.id}">${esc(x.name)}${x.unp?' · УНП '+esc(x.unp):''}</option>`).join('')}</select></div><div class="field"><label>Склад списания</label><select name="warehouse_id">${ws.map(w=>`<option value="${w.id}">${esc(w.name)}</option>`).join('')}</select></div><div class="field"><label>Тип документа</label><select name="doc_type"><option>Счёт</option><option>Счёт-фактура</option><option>Накладная</option></select></div><div class="field full"><label>Режим НДС и отображения цены</label><select name="vat_mode" id="doc-vat-mode" onchange="changeDocVatMode(this.value)"><option value="inclusive">Цена указана с НДС (НДС выделяется из цены)</option><option value="exclusive">Цена без НДС (НДС начисляется сверху)</option><option value="none">Без НДС (не начисляется)</option></select><small class="muted">Выберите режим, который соответствует налоговому статусу продавца и условиям реализации.</small></div></div><div class="panelhead" style="margin-top:20px"><h3>Товары</h3><button type="button" class="btn secondary" onclick="addDocLine()">+ Добавить позицию</button></div><div id="doc-lines"></div><div id="doc-total" class="right mono">Итого: 0,00 BYN</div><div class="formfoot"><button type="button" class="btn secondary" onclick="closeModal()">Отмена</button><button class="btn">Сохранить документ</button></div></form>`);addDocLine();$('#docform').onsubmit=async e=>{e.preventDefault();if(!docItems.length)return toast('Добавьте хотя бы один товар');let d=Object.fromEntries(new FormData(e.target));d.items=docItems;d.vat_mode=d.vat_mode||docVatMode;if(!d.customer_id)d.customer_id=null;try{await api('/api/documents',{method:'POST',body:JSON.stringify(d)});closeModal();toast('Документ сохранён');render()}catch(x){toast(x.message)}}}
function priceForMode(p,mode){if(!p)return 0;if(mode==='inclusive')return Number(p.sale_price||0);return Number(p.sale_price_without_vat||0)||Number(p.sale_price||0)/(1+Number(p.vat||0)/100)}
function changeDocVatMode(mode){docVatMode=mode;docItems.forEach(it=>{const p=products.find(x=>Number(x.id)===Number(it.product_id));it.price=priceForMode(p,mode)});drawDocLines()}
function addDocLine(){let id=Date.now()+Math.random(),p=products[0];docItems.push({key:id,product_id:p?.id,qty:1,price:priceForMode(p,docVatMode)});drawDocLines()}
function drawDocLines(){let box=$('#doc-lines');if(!box)return;box.innerHTML=docItems.map((it,i)=>`<div class="docline"><select class="input" onchange="changeDocProduct(${i},this.value)">${products.map(p=>`<option value="${p.id}" ${p.id==it.product_id?'selected':''}>${esc(p.article)} — ${esc(p.name)}</option>`).join('')}</select><input class="input" type="number" min="0.0001" step="0.0001" value="${it.qty}" onchange="docItems[${i}].qty=+this.value;drawDocLines()" title="Количество"><input class="input" type="number" min="0" step="0.0001" value="${it.price}" onchange="docItems[${i}].price=+this.value;drawDocLines()" title="Цена BYN"><button type="button" class="btn danger" onclick="docItems.splice(${i},1);drawDocLines()">×</button></div><div class="muted" style="margin:-4px 0 7px 3px">${esc(products.find(p=>p.id==it.product_id)?.tnved||'')} · ${esc(products.find(p=>p.id==it.product_id)?.manufacturer||'Производитель не указан')} · ${esc(products.find(p=>p.id==it.product_id)?.certificates||'Сертификат не привязан')}</div>`).join('');let sums=docItems.reduce((a,it)=>{const rate=docVatMode==='none'?0:Number(products.find(p=>p.id==it.product_id)?.vat||0),base=it.qty*it.price;let net=base,tax=0,gross=base;if(docVatMode==='inclusive'){tax=rate?base*rate/(100+rate):0;net=base-tax}else if(docVatMode==='exclusive'){tax=base*rate/100;gross=base+tax}a.net+=net;a.tax+=tax;a.gross+=gross;return a},{net:0,tax:0,gross:0});$('#doc-total').innerHTML=`Без НДС: ${money(sums.net)} BYN<br>НДС: ${money(sums.tax)} BYN<br><b>Итого: ${money(sums.gross)} BYN</b>`}
function changeDocProduct(i,v){let p=products.find(x=>x.id==v);docItems[i].product_id=+v;docItems[i].price=priceForMode(p,docVatMode);drawDocLines()}
async function exportDoc(id,format){let r=await fetch(`/api/documents/${id}/export?format=${format}`);if(!r.ok){let d=await r.json();return toast(d.error||'Ошибка выгрузки')}let blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`document_${id}.${format}`;a.click();URL.revokeObjectURL(url)}
// Shared PostgreSQL data is refreshed for every signed-in browser tab.
// This is polling (not a WebSocket); edits by another user appear within ~12 seconds.
setInterval(()=>{if(!authUser||document.hidden||!$('#modal').classList.contains('hidden'))return;const a=document.activeElement;if(a&&a.matches('input,textarea,select'))return;render()},12000);
initAuth();
